#!/usr/bin/env python3
"""Generate deterministic, dependency-free PGM stimuli for Hyproled tests."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

WIDTH = 48
HEIGHT = 32
MAX_VALUE = 255
OUT_DIR = Path(__file__).resolve().parent / "images"


def blank(value: int = 0) -> list[list[int]]:
    return [[value for _ in range(WIDTH)] for _ in range(HEIGHT)]


def put(image: list[list[int]], x: int, y: int, value: int) -> None:
    if 0 <= x < WIDTH and 0 <= y < HEIGHT:
        image[y][x] = value


def rect(image: list[list[int]], x0: int, y0: int, x1: int, y1: int, value: int, *, fill: bool = True) -> None:
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            if fill or x in (x0, x1) or y in (y0, y1):
                put(image, x, y, value)


def line(image: list[list[int]], x0: int, y0: int, x1: int, y1: int, value: int) -> None:
    # These fixtures use axis-aligned lines; keep rasterization exact.
    if x0 == x1:
        for y in range(min(y0, y1), max(y0, y1) + 1):
            put(image, x0, y, value)
    elif y0 == y1:
        for x in range(min(x0, x1), max(x0, x1) + 1):
            put(image, x, y0, value)
    else:
        raise ValueError("fixture line must be horizontal or vertical")


FONT_3X5 = {
    "H": ("101", "101", "111", "101", "101"),
    "Y": ("101", "101", "010", "010", "010"),
    "P": ("110", "101", "110", "100", "100"),
    "R": ("110", "101", "110", "101", "101"),
    "O": ("111", "101", "101", "101", "111"),
    "L": ("100", "100", "100", "100", "111"),
    "E": ("111", "100", "110", "100", "111"),
    "D": ("110", "101", "101", "101", "110"),
}


def text(image: list[list[int]], value: str, x: int, y: int, scale: int = 1, intensity: int = 255) -> None:
    cursor = x
    for char in value:
        glyph = FONT_3X5[char]
        for gy, row in enumerate(glyph):
            for gx, bit in enumerate(row):
                if bit == "1":
                    for sy in range(scale):
                        for sx in range(scale):
                            put(image, cursor + gx * scale + sx, y + gy * scale + sy, intensity)
        cursor += 4 * scale


def fixtures() -> dict[str, list[list[int]]]:
    images: dict[str, list[list[int]]] = {}

    image = blank()
    put(image, WIDTH // 2, HEIGHT // 2, 255)
    images["single-hot-pixel"] = image

    image = blank()
    line(image, WIDTH // 2, 4, WIDTH // 2, HEIGHT - 5, 255)
    images["vertical-1px-line"] = image

    image = blank()
    line(image, 4, HEIGHT // 2, WIDTH - 5, HEIGHT // 2, 255)
    images["horizontal-1px-line"] = image

    image = blank()
    text(image, "OLED", 14, 12, intensity=255)
    images["text-oled"] = image

    image = blank()
    # A simple high-contrast emblem: nested outline, stem, and detached dot.
    rect(image, 15, 7, 32, 24, 230, fill=False)
    rect(image, 19, 11, 28, 20, 255, fill=False)
    line(image, 23, 12, 23, 19, 255)
    put(image, 23, 16, 0)
    rect(image, 35, 20, 37, 22, 255)
    images["logo-outline"] = image

    image = blank()
    rect(image, 13, 8, 34, 23, 224, fill=True)
    images["uniform-rectangle"] = image

    image = blank()
    # Deliberately touches all four borders to expose black-edge clipping.
    line(image, 0, 0, WIDTH - 1, 0, 255)
    line(image, 0, HEIGHT - 1, WIDTH - 1, HEIGHT - 1, 255)
    line(image, 0, 0, 0, HEIGHT - 1, 255)
    line(image, WIDTH - 1, 0, WIDTH - 1, HEIGHT - 1, 255)
    rect(image, 0, 0, 3, 3, 180, fill=True)
    rect(image, WIDTH - 4, HEIGHT - 4, WIDTH - 1, HEIGHT - 1, 180, fill=True)
    images["edge-markers"] = image

    image = blank()
    # Synthetic static desktop: top panel, left sidebar, text rows and controls.
    rect(image, 0, 0, WIDTH - 1, 3, 72, fill=True)
    rect(image, 0, 4, 7, HEIGHT - 1, 48, fill=True)
    for row, intensity in ((7, 210), (13, 170), (19, 210), (25, 150)):
        line(image, 11, row, 31, row, intensity)
        for offset in (0, 3, 8, 11, 14, 18):
            put(image, 11 + offset, row - 1, intensity // 2)
    rect(image, 35, 8, 44, 15, 190, fill=False)
    rect(image, 36, 9, 43, 14, 110, fill=True)
    rect(image, 35, 20, 44, 27, 230, fill=False)
    images["mixed-desktop-ui"] = image

    image = blank()
    for y in range(HEIGHT):
        for x in range(WIDTH):
            image[y][x] = round(255 * (0.15 + 0.55 * x / (WIDTH - 1) + 0.30 * y / (HEIGHT - 1)))
    rect(image, 8, 7, 18, 17, 255, fill=False)
    rect(image, 29, 13, 40, 24, 24, fill=True)
    images["gradient-scene"] = image

    return images


def encode_pgm(name: str, image: list[list[int]]) -> str:
    lines = [
        "P2",
        f"# Synthetic Hyproled stimulus: {name}",
        "# Generated by tests/fixtures/generate_images.py; do not edit manually.",
        f"{WIDTH} {HEIGHT}",
        str(MAX_VALUE),
    ]
    lines.extend(" ".join(str(value) for value in row) for row in image)
    return "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="verify committed fixtures without modifying them")
    parser.add_argument("--output-dir", type=Path, default=OUT_DIR, help="fixture output directory")
    args = parser.parse_args()

    expected = {f"{name}.pgm": encode_pgm(name, image) for name, image in fixtures().items()}
    args.output_dir.mkdir(parents=True, exist_ok=True)
    failed = False

    for filename, content in expected.items():
        path = args.output_dir / filename
        if args.check:
            if not path.is_file() or path.read_text(encoding="ascii") != content:
                print(f"MISMATCH: {path}", file=sys.stderr)
                failed = True
        else:
            path.write_text(content, encoding="ascii", newline="\n")
            print(f"wrote {path}")

    if args.check:
        actual = {path.name for path in args.output_dir.glob("*.pgm")}
        missing = set(expected) - actual
        extra = actual - set(expected)
        if missing or extra:
            print(f"fixture set mismatch: missing={sorted(missing)}, extra={sorted(extra)}", file=sys.stderr)
            failed = True
        if not failed:
            print(f"verified {len(expected)} deterministic PGM fixtures")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())
